"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3876],{23876:n=>{n.exports=JSON.parse('{"schemaVersion":1,"locale":"ru","slug":"08-iis-i-nalogi","title":"Урок 08. ИИС-3 и налоги: Налоговый щит инвестора","sourceFingerprint":"c5a7a82f92e2717716864c08e6c476cd51d97ac11940b928e81fb741a388ff99","blocks":[{"id":"b001","markdown":"# Глава 8. Налоговый щит инвестора: как удержать прибыль с помощью ИИС-3 и льгот владения"},{"id":"b002","markdown":"> \xabПрибыль от удачной сделки всегда сопряжена с рыночной неопределённостью. Налоговая оптимизация — единственный способ повысить доходность портфеля со стопроцентной гарантией и нулевым риском\xbb.  \\n> — *MakeCash Книга, Том II: \xabЗащита капитала: 20 лет против инфляции\xbb*"},{"id":"b003","markdown":"⏱ *Время вдумчивого чтения: 6 минут*"},{"id":"b004","markdown":"Начинающие инвесторы часто упускают налоговые издержки из виду: брокер вычитает тринадцать процентов незаметно при выводе средств или в конце декабря, создавая иллюзию несущественных потерь. Однако на дистанции в десять-двадцать лет неоптимизированный налог на доходы физических лиц (НДФЛ) способен отнять до трети итогового сложного процента."},{"id":"b005","markdown":"Российское финансовое законодательство даёт частному инвестору мощные инструменты для сохранения дохода. Чтобы не отдавать государству лишнее, достаточно грамотно подобрать тип торгового счёта и соблюдать инвестиционную дисциплину."},{"id":"b006","markdown":"## Анатомия инвестиционного НДФЛ: за что и сколько забирает ФНС"},{"id":"b007","markdown":"Любой финансовый результат от операций на фондовом рынке подлежит налогообложению по стандартной прогрессивной шкале:"},{"id":"b008","markdown":"* **13%** — базовый тариф, если суммарный доход инвестора за календарный год не превысил **2,4 миллиона рублей**;\\n* **15%** — ставка на сумму превышения указанного порога в 2,4 млн ₽ (для более высоких доходов шкала поднимается вплоть до максимальных ступеней)."},{"id":"b009","markdown":"Фискальной нагрузке подлежат три ключевые статьи доходов:"},{"id":"b010","markdown":"1. **Курсовой прирост:** положительная разница между стоимостью продажи ценной бумаги (акции, облигации, пая биржевого фонда) и ценой её приобретения, очищенная от брокерских и биржевых комиссий.\\n2. **Купонный доход:** выплаты по облигациям любого типа, включая государственные долговые бумаги (ОФЗ).\\n3. **Дивидендный поток:** отчисления компаний держателям акций (налог удерживается в момент выплаты эмитентом)."},{"id":"b011","markdown":"Брокер внутри российской юрисдикции несёт обязанности **налогового агента**. Это избавляет от необходимости заполнять декларацию вручную: брокерская компания самостоятельно производит взаимозачёт, удерживает налог при снятии рублей с баланса либо списывает его по результатам декабря."},{"id":"b012","markdown":"> **Правило сальдирования убытков:** неудачные сделки снижают налогооблагаемую базу. Если за год на одной позиции вы заработали 60 000 ₽, а на другой зафиксировали убыток 20 000 ₽, НДФЛ будет начислен исключительно на чистую прибыль — с 40 000 ₽ (налог составит 5 200 ₽ вместо 7 800 ₽). В рамках одного брокера взаимозачёт происходит автоматически; финансовые результаты разных платформ можно объединить через подачу декларации 3-НДФЛ."},{"id":"b013","markdown":"## Льгота долгосрочного владения (ЛДВ): награда за терпение"},{"id":"b014","markdown":"Если инвестор не занимается спекуляциями и держит активы в портфеле свыше трёх лет, закон освобождает положительный результат от продажи таких инструментов от НДФЛ."},{"id":"b015","markdown":"* **Финансовый лимит:** освобождается до **3 000 000 ₽ чистой прибыли за каждый полный год владения**. Соответственно, за три года непрерывного удержания лимит составит **9 000 000 ₽**, за пять лет — **15 000 000 ₽**.\\n* **Критерии применения:** активы должны обращаться на отечественных биржевых торгах (акции, облигации, БПИФы) и быть приобретены позже 1 января 2014 года.\\n* **Специфика расчёта:** трёхлетний таймер тикает отдельно для каждого купленного лота по правилу FIFO (первым пришёл — первым ушёл)."},{"id":"b016","markdown":"⚠️ *Важное ограничение:* ЛДВ нейтрализует налог только с прироста рыночной стоимости. Поступающие дивиденды и купоны на обычном брокерском счёте облагаются НДФЛ в стандартном порядке без льгот."},{"id":"b017","markdown":"## ИИС-3: флагманский счёт с двойной налоговой защитой"},{"id":"b018","markdown":"Индивидуальный инвестиционный счёт третьего типа (действует для всех счетов, открываемых с 2024 года) объединил преимущества старых форматов ИИС. Если ранее приходилось выбирать между возвратом налога со взносов и освобождением прибыли, то ИИС-3 предоставляет **обе преференции одновременно**."},{"id":"b019","markdown":"```\\n┌────────────────────────────────────────────────────────────────────────┐\\n│                        АРХИТЕКТУРА ЛЬГОТ ИИС-3                         │\\n├──────────────────────────────────┬─────────────────────────────────────┤\\n│   ВЫЧЕТ НА ВХОДЕ (НА ВЗНОСЫ)     │     ОСВОБОЖДЕНИЕ НА ВЫХОДЕ          │\\n│                                  │                                     │\\n│  Возврат 13% от суммы пополнения │  Полное освобождение от НДФЛ        │\\n│  (до 52 000 ₽ ежегодно при базе  │  прибыли от сделок и купонов        │\\n│  до 400 000 ₽; до 60 000 ₽ при   │  при закрытии счёта.                │\\n│  ставке НДФЛ 15%).               │  Лимит необлагаемой прибыли —       │\\n│  Требуется официальный доход.    │  до 30 000 000 ₽ за весь срок.      │\\n└──────────────────────────────────┴─────────────────────────────────────┘\\n```"},{"id":"b020","markdown":"### Ключевые параметры и ограничения ИИС-3:"},{"id":"b021","markdown":"* **Срок жизни счёта:** для договоров, зарегистрированных в 2024–2026 годах, минимальный период удержания средств без потери налоговых преференций составляет **5 лет**. С 2027 года этот порог начнёт поэтапно увеличиваться на один год, пока не достигнет 10 лет.\\n* **Запрет на вывод:** частичное изъятие капитала невозможно. Досрочное закрытие аннулирует все полученные вычеты: их придётся вернуть государству вместе с начисленными пенями, а с финансового результата брокер удержит стандартный налог. Единственное законодательное исключение — снятие денег на оплату тяжелых видов медицинских услуг из утверждённого перечня.\\n* **Правило закрытия:** в год ликвидации счёта право на вычет по взносам не предоставляется. Оптимально закрывать контракт в начале следующего календарного года (в январе-феврале).\\n* **Инструменты:** разрешены только ценные бумаги РФ (ОФЗ, корпоративные облигации, акции, биржевые фонды российских управляющих компаний).\\n* **Мультисчета:** инвестору разрешено одновременно владеть пулом до трёх ИИС-3 у разных брокеров.\\n* **Сводный лимит:** потолок взносов для получения ежегодного вычета (400 000 ₽) является общим для ИИС-3, Программы долгосрочных сбережений (ПДС) и добровольных взносов в НПФ.\\n* **Страховка:** с 1 января 2026 года для счетов ИИС-3 начинает действовать механизм государственного страхования активов на сумму до **1,4 млн ₽** на случай аннулирования лицензии или банкротства посредника (в добровольном порядке среди лицензированных брокеров; рыночные риски просадки цен страховка не покрывает)."},{"id":"b022","markdown":"## Карта распределения капитала по горизонтам"},{"id":"b023","markdown":"Не отправляйте все свободные деньги на один счёт. Балансируйте активы исходя из времени, через которое они вам потребуются:"},{"id":"b024","markdown":"| Горизонт задач | Рекомендуемый инструмент | Налоговая стратегия |\\n| :--- | :--- | :--- |\\n| **Краткосрок (до 1–3 лет)** + резервный фонд | Вклады, накопительные счета, фонды ликвидности (LQDT) | Налоговые льготы не успеют включиться. Приоритет — мгновенный доступ и отсутствие риска просадки тела капитала. |\\n| **Среднесрок (от 3 до 5 лет)** | Стандартный брокерский счёт | Покупка надёжных активов без продажи минимум 3 года для автоматической активации ЛДВ. Свобода вывода средств в любой день без штрафов. |\\n| **Долгосрок (от 5 лет и выше)** | Индивидуальный инвестиционный счёт (ИИС-3) | Максимальный налоговый буст: возврат уплаченного НДФЛ со взносов плюс безналоговый купонный доход и курсовой прирост до 30 млн ₽. |"},{"id":"b025","markdown":"## \uD83E\uDDEE Расчёт на полях тетради"},{"id":"b026","markdown":"**Задача:** Сравнить результаты консервативного размещения капитала на ИИС-3 и обычном брокерском счёте на пятилетнем горизонте."},{"id":"b027","markdown":"**Входные параметры:**\\n* Ежегодное пополнение: **400 000 ₽** в начале каждого года (суммарно внесено: 2 000 000 ₽).\\n* Ставка НДФЛ инвестора с официальной зарплаты: **13%**.\\n* Среднегодовая доходность портфеля (ОФЗ + корпоративные бонды): **10% годовых**.\\n* Срок удержания: **5 лет**."},{"id":"b028","markdown":"```\\nДИНАМИКА НАКОПЛЕНИЙ (ИИС-3 ПРОТИВ БРОКЕРСКОГО СЧЁТА):"},{"id":"b029","markdown":"Год 1: Взнос 400 000 ₽ → Капитал к концу года: 440 000 ₽\\nГод 2: Взнос 400 000 ₽ + возврат 52 000 ₽ → Капитал с процентами: 976 000 ₽\\nГод 3: Взнос 400 000 ₽ + возврат 52 000 ₽ → Капитал с процентами: 1 565 600 ₽\\nГод 4: Взнос 400 000 ₽ + возврат 52 000 ₽ → Капитал с процентами: 2 214 160 ₽\\nГод 5: Взнос 400 000 ₽ + возврат 52 000 ₽ → Капитал с процентами: 2 927 576 ₽\\n```"},{"id":"b030","markdown":"* **Прямой возврат НДФЛ от государства:** 52 000 ₽ \xd7 5 лет = **260 000 ₽**.\\n* **Прибыль от реинвестирования и процентов:** около 927 576 ₽.\\n* **Налог при закрытии счёта через 5 лет:**\\n  * На *ИИС-3*: **0 ₽** (купоны и курсовая разница укладываются в лимит 30 млн ₽).\\n  * На *обычном счёте* (без льготы на купоны): налог 13% с купонного потока забрал бы свыше **120 000 ₽**, а возврат в 260 000 ₽ отсутствовал бы вовсе."},{"id":"b031","markdown":"**Итоговый чистый профит от использования ИИС-3:** инвестор получает свыше **380 000 ₽** чистого налогового преимущества при абсолютно идентичном наборе ценных бумаг."}],"terms":[{"id":"iis-3","term":"ИИС-3","definition":"индивидуальный инвестиционный счёт, сочетающий вычет на взнос и освобождение дохода от НДФЛ."},{"id":"ldv","term":"ЛДВ","definition":"льгота долгосрочного владения ценными бумагами более 3 лет."},{"id":"nalogovyj-agent","term":"Налоговый агент","definition":"российский брокер, который сам считает и удерживает НДФЛ клиента."}],"quizzes":[{"id":"q1","q":"Инвестор открыл обычный брокерский счёт в марте 2024 года, приобрёл паи индексного фонда на 300 000 ₽ и полностью продал их в мае 2025 года за 420 000 ₽. Иных операций не совершалось. Как брокер рассчитает налог?","options":["Налог не удерживается, поскольку прибыль не превысила 3 млн рублей.","Брокер удержит 13% с прибыли в 120 000 ₽ (15 600 ₽), так как срок непрерывного владения составил менее трёх лет.","Придётся заплатить повышенный налог 15% за краткосрочные спекуляции."],"correct":1,"explanation":""},{"id":"q2","q":"Какое ключевое преимущество получает владелец ИИС-3 по сравнению со стандартным брокерским счётом в части купонного дохода по облигациям?","options":["По ИИС-3 купоны выплачиваются в двойном размере за счёт государственных субсидий.","На обычном счёте налог с купонов удерживается всегда, а на ИИС-3 при закрытии счёта после истечения 5 лет купонный доход освобождается от НДФЛ (в пределах 30 млн ₽ общей прибыли).","Купоны на ИИС-3 освобождаются от налога только в случае покупки высокорискованных акций."],"correct":1,"explanation":""},{"id":"q3","q":"Сотрудник с официальной зарплатой открыл ИИС-3 в марте 2024 года и ежегодно вносит по 400 000 ₽. Осенью 2026 года ему срочно потребовались деньги на покупку машины, и он закрыл счёт. Каковы фискальные последствия?","options":["Он сможет забрать деньги без потерь, так как держал счёт больше 2 лет.","Деньги конфискуются в пользу государства за нарушение договора.","Ему придётся вернуть все ранее полученные вычеты на взносы с уплатой пеней, а с полученного инвестиционного дохода брокер спишет НДФЛ."],"correct":2,"explanation":""}],"officialSources":[]}')}}]);